]//Assignment[
  (: assignment target matches a @GuardedBy("this") field :)
  (DirectlyAssignableExpression|AssignableExpression)//T-Identifier[
    @Text = ancestor::ClassBody[1]//PropertyDeclaration[
      not(ancestor::FunctionBody)
      and .//Annotation[.//T-Identifier[@Text='GuardedBy']]//T-LineStrText[@Text='this']
    ]/VariableDeclaration/@Identifier
  ]
  (: not inside synchronized(this) block :)
  and not(ancestor::LambdaLiteral[
