rule.example:
class Bad {
    @GuardedBy("this")
    var txt: String = ""

    fun getText(): String { return txt } // bad - not synchronized
    fun setText(t: String) { txt = t }   // bad - not synchronized
}

class Good {
    @GuardedBy("this")
    var txt: String = ""

    @Synchronized
    fun getText(): String { return txt } // good
    @Synchronized
    fun setText(t: String) { txt = t }   // good
}

